{
  "title": "A Sunday Close to the Heart",
  "summary": "A gentle day around the Zócalo and Chapultepec, keeping every ride short and every stop worth the walk.",
  "stops": [
    {
      "poi_id": "p8",
      "kind": "activity",
      "must_do_id": "m1",
      "note": "The one big journey of the day, kept because it simply cannot be missed."
    },
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "History with a heartbeat, right in the centre and easy on the legs."
    },
    {
      "poi_id": "p3",
      "kind": "activity",
      "must_do_id": null,
      "note": "A quick wander through the Zócalo, because local life starts in the square."
    },
    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch beside the centre, with options for every taste at the table."
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": null,
      "note": "A green pause in Chapultepec, close enough to feel like a stroll, not a trip."
    },
    {
      "poi_id": "p15",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner near the park, easygoing and kind to the veggie lovers among us."
    }
  ]
}

{
  "title": "A Sunday Close to the Zócalo",
  "summary": "A gentle day around the historic heart, with a market wander, a museum visit, and a long lunch nearby.",
  "stops": [
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "Templo Mayor keeps the history lovers happy, and it sits right beside our next stop."
    },
    {
      "poi_id": "p3",
      "kind": "activity",
      "must_do_id": null,
      "note": "A quick lap of the Zócalo for local life and a bit of people-watching, no long ride needed."
    },
    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch at Al-Andalus, just around the corner, with halal and vegetarian options for the crew."
    },
    {
      "poi_id": "p9",
      "kind": "activity",
      "must_do_id": null,
      "note": "Mercado de Coyoacán is a short ride from the centre, so the market lovers still get their fill."
    },
    {
      "poi_id": "p15",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner at Por Siempre Vegana, close to the market, keeps the day light and the travel short."
    }
  ]
}
